// Unscoped enum with problematic implicit conversions
enum ColorUnscoped { black, white, red };
ColorUnscoped color1 = red; // color1 is 2

if (color1 < 14.5) { /* Compiles, but is semantically meaningless */ }
int colorValue = color1; // Implicit conversion to int is allowed

// Scoped enum enforces type safety
enum class ColorScoped { black, white, red };
ColorScoped color2 = ColorScoped::red;

// if (color2 < 14.5) { /* ERROR: No operator< matches these operands */ }
// int colorValue2 = color2; /* ERROR: No implicit conversion */

// Explicit cast is required to get the underlying value
int colorValue3 = static_cast<int>(color2); // OK, conversion is explicit
